{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude && ls -la && ls -la data ref ref/ccmc 2>/dev/null | head -50; ls /home/scabot/miniconda3/envs/ 2>/dev/null; nproc; free -g",
  "description": "Inspect workspace and reference folders"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude && cat ref/ccmc/run_metadata.json; echo; cat ref/ccmc/Jan_Deca_120925_SH_1_control_file.txt; echo; cat ref/ccmc/Jan_Deca_120925_SH_1_cme_param.txt; head -20 ref/ccmc/Jan_Deca_120925_SH_1_wsadu_gongz.lst; wc -l ref/ccmc/Jan_Deca_120925_SH_1_wsadu_gongz.lst; tail -5 ref/ccmc/Jan_Deca_120925_SH_1_wsadu_gongz.lst",
  "description": "Read CCMC reference files"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/ref/ccmc && head -c 3000 test_pd.txt; echo; grep -o 'href=\"[^\"]*\"' viewrun.html | sort -u | head -80; grep -o 'https\\?://[^\" ]*' post_3i.html idl1d_3i.html | sort -u | head -40",
  "description": "Inspect CCMC HTML link structure"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/ref && grep -n -i -E 'enlil|wsa|stereo|solar wind|ccmc' main.txt | head -60",
  "description": "Search preprint for solar wind references"
}

{
  "command": "curl -s -m 60 https://gong.nso.edu/data/magmap/ | sed 's/<[^>]*>/ /g' | grep -v '^\\s*$' | head -60",
  "description": "Inspect GONG magmap directory listing"
}

{
  "command": "curl -s -m 60 https://gong.nso.edu/data/magmap/ | grep -o 'href=\"[^\"]*\"' | sort -u | head -60; echo ---; curl -s -m 60 https://gong.nso.edu/data/magmap/QR/ | grep -o 'href=\"[^\"]*\"' | head -40",
  "description": "List GONG magmap links and QR directory"
}

{
  "command": "curl -s -m 60 https://gong.nso.edu/data/magmap/QR/ | grep -o 'href=\"[^\"]*\"' | sed 's/href=//' | tr '\\n' ' '; echo; curl -s -m 60 https://gong.nso.edu/data/magmap/QR/zqs/ | grep -o 'href=\"[^\"]*\"' | tail -20",
  "description": "List QR subdirectories and zqs"
}

{
  "command": "curl -s -m 60 https://gong.nso.edu/data/magmap/QR/zqs/202511/ | grep -o 'href=\"[^\"]*\"' | head -10; curl -s -m 60 https://gong.nso.edu/data/magmap/QR/zqs/202511/ | grep -o 'href=\"[^\"]*\"' | wc -l; d=$(curl -s -m 60 https://gong.nso.edu/data/magmap/QR/zqs/202511/ | grep -o 'href=\"mrzqs[^\"]*/\"' | head -1 | sed 's/href=\"//;s/\"//'); echo $d; curl -s -m 60 https://gong.nso.edu/data/magmap/QR/zqs/202511/$d | sed 's/<[^>]*>/ /g' | grep -E 'fits|gz' | head -30",
  "description": "Inspect zqs month directory layout"
}

{
  "command": "curl -s -m 60 https://gong.nso.edu/adapt/maps/ | grep -o 'href=\"[^\"]*\"' | head -30; echo ---; curl -s -m 60 https://gong.nso.edu/adapt/maps/gong/ | grep -o 'href=\"[^\"]*\"' | tail -15",
  "description": "Inspect ADAPT maps directory layout"
}

{
  "command": "curl -s -m 60 https://gong.nso.edu/adapt/maps/gong/2025/ | sed 's/<[^>]*>/ /g' | grep -E 'fts|fits|gz' | grep -E '202511(2[4-6])' | head -30; curl -s -m 60 https://gong.nso.edu/adapt/maps/gong/2025/ | sed 's/<[^>]*>/ /g' | grep -cE 'fts|fits'",
  "description": "List ADAPT GONG 2025 files near Nov 25"
}

{
  "command": "ls /home/scabot/miniconda3/envs/mhd_claude/bin/python 2>/dev/null && /home/scabot/miniconda3/envs/mhd_claude/bin/python -c \"import sunpy,h5py,astropy;print(sunpy.__version__,astropy.__version__)\"; cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/data && mkdir -p gong adapt hmi cme ips wsa_ccmc qc scripts_rs && ls; S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; mkdir -p $S/ccmc; curl -s -m 90 -o $S/ccmc/run_files.html -w '%{http_code} %{size_download}\\n' 'https://ccmc.gsfc.nasa.gov/ror/results/run_files.php?runnumber=Jan_Deca_120925_SH_1'",
  "description": "Check env, create dirs, fetch CCMC run file listing"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/data && find . -maxdepth 2 | head -50",
  "description": "List existing data folder contents"
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad/ccmc; for i in 1 2 3 4 5 6; do r=$(curl -s -m 120 -o $S/run_files.html -w '%{http_code} %{size_download}' 'https://ccmc.gsfc.nasa.gov/ror/results/run_files.php?runnumber=Jan_Deca_120925_SH_1'); echo \"$i $r\"; case \"$r\" in 200*) break;; esac; sleep $((i*10)); done; head -c 600 $S/run_files.html",
  "description": "Retry CCMC run_files listing with backoff",
  "timeout": 600000
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad/ccmc; grep -o 'href=\"[^\"]*\"' $S/run_files.html | sed 's/href=\"//;s/\"$//' > $S/links.txt; wc -l $S/links.txt; grep -i wsa $S/links.txt | head -20; grep -ci wsa $S/links.txt; sed 's|/[^/]*$||' $S/links.txt | sort | uniq -c | sort -rn | head -20",
  "description": "Extract links from CCMC run file listing"
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad/ccmc; grep 'ror/api/get_run_file.php' $S/links.txt | sed 's/.*filename=//' | grep -v -E '^(bnd|bnd2|vel3e1|den3e1|vel3|vel2e1|vel1|den3|den2e1|den1|stb1dej|sta1dej|sho1o4|gifs|evo4o1|evo10o1|jmap2)/' | head -80; grep 'ror/api/get_run_file.php' $S/links.txt | sed 's/.*filename=//' | grep -E '^bnd/' | head -5; grep 'ror/api/get_run_file.php' $S/links.txt | sed 's/.*filename=//' | grep -E '^bnd2/' | head -5",
  "description": "List non-plot files from CCMC run"
}
